def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for string in lst:
        if not all(char in ['(', ')'] for char in string):
            return 'No'

    count_opening = lst[0].count('(') + lst[1].count('(')
    count_closing = lst[0].count(')') + lst[1].count(')')

    if (count_opening + count_closing) % 2 != 0:
        return 'No'

    stack = []
    for char in lst[0] + lst[1]:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    if not stack:
        return 'Yes'
    else:
        return 'No'

