def check_equal_count(brackets: str) -> bool:
    return brackets.count('<') == brackets.count('>')

def check_correctly_nested(brackets: str) -> bool:
    count = 0
    for char in brackets:
        if char == '<':
            count += 1
        elif char == '>':
            count -= 1
            if count < 0:
                return False
    return count == 0

def correct_bracketing(brackets: str) -> bool:
    if not check_valid_characters(brackets):
        return False
    if not check_equal_count(brackets):
        return False
    return check_correctly_nested(brackets)

